import{_ as e,o,c as r,ag as s}from"./chunks/framework.BZohXCq9.js";const u=JSON.parse('{"title":"Backend Stripe & Payment Code – Where It Lives & What It Does","description":"","frontmatter":{},"headers":[],"relativePath":"BACKEND_STRIPE_AND_PAYMENT_GUIDE.md","filePath":"BACKEND_STRIPE_AND_PAYMENT_GUIDE.md"}'),n={name:"BACKEND_STRIPE_AND_PAYMENT_GUIDE.md"};function a(i,t,c,d,l,g){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="backend-stripe-payment-code-–-where-it-lives-what-it-does" tabindex="-1">Backend Stripe &amp; Payment Code – Where It Lives &amp; What It Does <a class="header-anchor" href="#backend-stripe-payment-code-–-where-it-lives-what-it-does" aria-label="Permalink to &quot;Backend Stripe &amp; Payment Code – Where It Lives &amp; What It Does&quot;">​</a></h1><p>This document lists <strong>every backend file</strong> that contains Stripe or payment-related code and explains <strong>what each part does</strong> in plain terms.</p><hr><h2 id="quick-map-where-is-stripe-payment-code" tabindex="-1">Quick map: where is Stripe/payment code? <a class="header-anchor" href="#quick-map-where-is-stripe-payment-code" aria-label="Permalink to &quot;Quick map: where is Stripe/payment code?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Location</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>server/src/services/stripeService.js</strong></td><td>All direct Stripe API calls (accounts, Checkout, PaymentIntents, refunds, transfers, payouts)</td></tr><tr><td><strong>server/src/routes/stripeWebhook.routes.js</strong></td><td>Stripe webhooks (checkout.session.completed, payment_intent.succeeded, account.updated, etc.)</td></tr><tr><td><strong>server/src/jobs/t48ChargeJob.js</strong></td><td>T-48 job: charges students 48h before lesson using saved card (off-session)</td></tr><tr><td><strong>server/src/jobs/payoutJob.js</strong></td><td>Payout job: sends instructor share from Stripe balance to their bank</td></tr><tr><td><strong>server/src/graphql/resolvers/studentBooking.resolver.js</strong></td><td>Booking + Checkout: creates sessions, completes booking after payment, T-48 complete payment</td></tr><tr><td><strong>server/src/graphql/resolvers/refundRequest.resolver.js</strong></td><td>Refunds: calls Stripe refund + transfer reversal when admin approves</td></tr><tr><td><strong>server/src/graphql/resolvers.js</strong></td><td>Instructor Stripe Connect: create account, account link, verify onboarding, manual payout</td></tr><tr><td><strong>server/src/graphql/utils/instructorPaymentReady.js</strong></td><td>Helper: is instructor allowed to receive payments (Stripe verified)?</td></tr><tr><td><strong>server/src/services/transactionService.js</strong></td><td>Creates transaction records (stores stripePaymentIntentId, stripeRefundId, etc.)</td></tr><tr><td><strong>server/src/graphql/resolvers/transaction.resolver.js</strong></td><td>Platform commission settings (payoutMethods includes &quot;Stripe&quot;)</td></tr><tr><td><strong>server/src/index.js</strong></td><td>Mounts Stripe webhook route at <code>/webhooks/stripe</code> with raw body</td></tr><tr><td><strong>server/src/models/transaction.model.js</strong></td><td>Transaction schema with Stripe IDs (stripePaymentIntentId, stripeRefundId, etc.)</td></tr><tr><td><strong>server/src/models/studentBooking.model.js</strong></td><td>Booking/slot fields: stripePaymentIntentId, stripeCustomerId, paymentStatus, etc.</td></tr></tbody></table><hr><h2 id="_1-server-src-services-stripeservice-js" tabindex="-1">1. <code>server/src/services/stripeService.js</code> <a class="header-anchor" href="#_1-server-src-services-stripeservice-js" aria-label="Permalink to &quot;1. `server/src/services/stripeService.js`&quot;">​</a></h2><p><strong>What it is:</strong> The single place that talks to Stripe’s API. No other file calls <code>stripe.*</code> directly; they all use functions from here.</p><p><strong>What it does (function by function):</strong></p><ul><li><p><strong><code>createExpressAccount(email)</code></strong><br> Creates a Stripe Connect <strong>Express</strong> account for an instructor (country CH, card_payments + transfers). Used when an instructor starts “Connect with Stripe”.</p></li><li><p><strong><code>setManualPayoutSchedule(accountId)</code></strong><br> Sets the connected account to <strong>manual</strong> payouts. Money stays in the instructor’s Stripe balance until your app creates a payout (via Payouts API).</p></li><li><p><strong><code>createAccountLink(accountId, paths)</code></strong><br> Creates a Stripe <strong>account link</strong> for onboarding. The instructor is redirected to Stripe to complete identity/bank details. <code>refreshPath</code> and <code>returnPath</code> are your frontend URLs (e.g. <code>/payment/refresh</code>, <code>/payment/complete</code>).</p></li><li><p><strong><code>retrieveAccount(accountId)</code></strong><br> Fetches the full Stripe account (e.g. to check <code>charges_enabled</code>, <code>payouts_enabled</code>, requirements).</p></li><li><p><strong><code>accountToStripeSnapshot(account)</code></strong><br> Converts Stripe’s account object into the shape you save in DB: <code>stripeAccount.*</code>, <code>onboardingStatus</code>, <code>isActive</code>. Used after onboarding and in webhooks.</p></li><li><p><strong><code>getCommissionSplit(amountChf, instructor, platformSettings)</code></strong><br> Splits the lesson amount into platform commission and instructor share (percentage or fixed). Returns <code>{ dspCommission, instructorAmount }</code> in CHF.</p></li><li><p><strong><code>createPaymentIntentForBooking(opts)</code></strong><br> Creates (and optionally confirms) a <strong>PaymentIntent</strong>. Used for:</p><ul><li><strong>Instant payment</strong> (card on file): confirm immediately, optional 3DS.</li><li><strong>T-48 off-session</strong>: <code>offSession: true</code>, charges saved card later. Supports <strong>destination charge</strong>: part of the amount goes to the instructor’s connected account (<code>transferData</code>).</li></ul></li><li><p><strong><code>createCheckoutSessionForBooking(opts)</code></strong><br> Creates a Stripe <strong>Checkout Session</strong> for a booking:</p><ul><li><strong>mode: &quot;payment&quot;</strong> → student pays now; one PaymentIntent for the full amount; destination charge to instructor.</li><li><strong>mode: &quot;setup&quot;</strong> → only saves the card (SetupIntent); no charge; used when lesson is &gt;48h away (deferred payment).</li></ul></li><li><p><strong><code>createCustomer(opts)</code></strong><br> Creates a Stripe <strong>Customer</strong> (by email). Used in deferred flow so the Checkout Session has a <code>customer</code> and you can charge the saved payment method later.</p></li><li><p><strong><code>retrieveCheckoutSession(sessionId)</code></strong><br> Loads a Checkout Session with <code>payment_intent</code>, <code>setup_intent</code>, <code>customer</code> expanded. Used when the student returns from Stripe to complete the booking.</p></li><li><p><strong><code>retrieveSetupIntent(setupIntentId)</code></strong> / <strong><code>retrievePaymentMethod(paymentMethodId)</code></strong><br> Used by webhook and “complete deferred booking” to get customer ID and payment method after setup.</p></li><li><p><strong><code>createTransferToInstructor(opts)</code></strong><br> Transfers money from <strong>platform</strong> Stripe balance to instructor’s <strong>connected account</strong> (for destination charges the transfer is created by Stripe; this is for other flows if you use separate charges + transfer).</p></li><li><p><strong><code>createManualPayoutForInstructor(opts)</code></strong><br> Creates a <strong>Payout</strong> from the instructor’s Stripe balance to their bank. Used by the payout job because you use manual payouts.</p></li><li><p><strong><code>createRefund(opts)</code></strong><br> Refunds a PaymentIntent (full or partial). Money goes back to the student’s card.</p></li><li><p><strong><code>getTransferIdFromPaymentIntent(paymentIntentId)</code></strong><br> For a destination charge, gets the <strong>Transfer</strong> ID from the PaymentIntent’s latest charge. Needed to reverse the instructor’s share when you refund.</p></li><li><p><strong><code>createTransferReversal(opts)</code></strong><br> Reverses part (or all) of a transfer. Used on refund: first refund to student, then reverse the instructor’s share so the platform doesn’t eat the cost.</p></li><li><p><strong><code>retrievePaymentIntent(paymentIntentId)</code></strong><br> Loads a PaymentIntent (e.g. to check status after 3DS or in webhook).</p></li><li><p><strong><code>confirmPaymentIntent(paymentIntentId, returnUrl)</code></strong><br> Confirms a PaymentIntent with a <code>return_url</code> (for 3DS redirect). Used when the student completes payment on the “complete payment” page.</p></li></ul><p>Constants: <strong><code>DEFAULT_CURRENCY</code></strong> (<code>&quot;chf&quot;</code>), <strong><code>CENTIMES_PER_UNIT</code></strong> (100 for CHF), <strong><code>FRONTEND_BASE</code></strong> (used in success/cancel URLs).</p><p><strong>Show only CHF on Stripe Checkout (no PKR or other local currency):</strong><br> The app charges only in CHF. In code we set <strong><code>adaptive_pricing: { enabled: false }</code></strong> when creating the Checkout Session so Stripe does not show the customer’s local currency. If both currencies still appear (e.g. after an SDK or API version change), turn off <strong>Adaptive Pricing</strong> in the Stripe Dashboard: <strong><a href="https://dashboard.stripe.com/settings/adaptive-pricing" target="_blank" rel="noreferrer">Settings → Adaptive Pricing</a></strong> and disable it for Checkout.</p><hr><h2 id="_2-server-src-routes-stripewebhook-routes-js" tabindex="-1">2. <code>server/src/routes/stripeWebhook.routes.js</code> <a class="header-anchor" href="#_2-server-src-routes-stripewebhook-routes-js" aria-label="Permalink to &quot;2. `server/src/routes/stripeWebhook.routes.js`&quot;">​</a></h2><p><strong>What it is:</strong> HTTP endpoint that receives <strong>Stripe webhooks</strong>. Must be mounted with <strong>raw body</strong> (see <code>index.js</code>) so signature verification works.</p><p><strong>Route:</strong> <code>POST /webhooks/stripe</code> (mount path from <code>index.js</code>).</p><p><strong>What it does:</strong></p><ul><li>Verifies <strong><code>Stripe-Signature</code></strong> with <code>STRIPE_WEBHOOK_SECRET</code> and parses the event.</li><li>Deduplicates by <strong>event id</strong> (in-memory set) so the same event isn’t processed twice.</li><li><strong>Platform events</strong> (no <code>account</code> = your platform): <ul><li><strong><code>checkout.session.completed</code></strong><br> If mode is <strong>setup</strong> (deferred flow): finds booking by <code>metadata.bookingId</code>, gets <code>stripeCustomerId</code> and payment method from session/setup_intent, saves them on the booking and sets slots to <code>pending_payment</code>. So even if the user never hits your success URL, the booking is “card saved” and T-48 can charge later.</li><li><strong><code>payment_intent.succeeded</code></strong><ul><li><strong>Legacy:</strong> booking with <code>stripePaymentIntentId === pi.id</code> → already handled, respond OK.</li><li><strong>T-48 per-slot:</strong> find booking by <code>slots.paymentIntentId === pi.id</code>. Mark that slot paid, set charge amounts and commission, create <strong>transactions</strong> (student debit, platform receipt, instructor share, commission), and if all slots are paid set booking to <code>confirmed</code> and <code>stripePaymentIntentId</code>. Handles 3DS completion when the student finishes on Stripe’s page.</li></ul></li></ul></li><li><strong>Connect account events</strong> (event has <code>account</code> = instructor’s connected account): <ul><li><strong><code>account.updated</code></strong> → refresh instructor’s Stripe snapshot and <code>onboardingStatus</code> / <code>isActive</code>.</li><li><strong><code>account.application.deauthorized</code></strong> → mark account as disconnected / disabled.</li><li><strong><code>charge.dispute.created</code></strong> / <strong><code>charge.dispute.closed</code></strong> → set flags on instructor (e.g. <code>hasDisputes</code>).</li><li><strong><code>payout.failed</code></strong> / <strong><code>payout.paid</code></strong> → update instructor financial status (e.g. payouts blocked).</li></ul></li></ul><p>All handlers are defensive (try/catch, null checks) and respond <code>200 OK</code> so Stripe doesn’t retry unnecessarily.</p><hr><h2 id="_3-server-src-jobs-t48chargejob-js" tabindex="-1">3. <code>server/src/jobs/t48ChargeJob.js</code> <a class="header-anchor" href="#_3-server-src-jobs-t48chargejob-js" aria-label="Permalink to &quot;3. `server/src/jobs/t48ChargeJob.js`&quot;">​</a></h2><p><strong>What it is:</strong> A <strong>scheduled job</strong> that runs periodically (e.g. every few minutes). It finds slots that are <strong>within 48 hours</strong> of the lesson and still <strong>pending_payment</strong>, then charges the student’s saved card (off-session).</p><p><strong>What it does step by step:</strong></p><ul><li>Query: bookings that have at least one slot with <code>paymentStatus: &quot;pending_payment&quot;</code> and a saved <code>paymentMethod.paymentMethodId</code>.</li><li>For each such booking, get instructor (for Stripe account and commission).</li><li>For each slot with <code>pending_payment</code>: <ul><li>Compute <strong>slot start</strong> and <strong>charge time</strong> = slot start − 48h. If now &lt; charge time, skip (not yet in window).</li><li>If booking has no <strong><code>stripeCustomerId</code></strong>, mark slot <strong>payment_failed</strong> (can’t charge off-session) and continue.</li><li>Call <strong><code>createPaymentIntentForBooking</code></strong> with: <ul><li><code>offSession: true</code>, saved <code>paymentMethodId</code> and <code>stripeCustomerId</code></li><li><code>transferData</code> = instructor’s share to their connected account</li><li><strong>idempotency key</strong> = <code>t48-{bookingId}-{slotId}</code> so the same slot isn’t charged twice.</li></ul></li></ul></li><li><strong>If <code>requiresAction</code></strong> (3DS): update slot to <code>requires_action</code>, store <code>paymentIntentId</code>, send “payment requires action” email. Student must complete payment on your “complete payment” page.</li><li><strong>If status !== &quot;succeeded&quot;</strong>: mark slot <strong>payment_failed</strong>.</li><li><strong>If succeeded</strong>: update slot to <strong>paid</strong>, set <code>paymentIntentId</code>, <code>chargedAt</code>, <code>chargeAmount</code>, <code>dspCommission</code>, <code>instructorAmount</code>, create <strong>transactions</strong> (student debit, platform receipt, instructor share, commission). If all slots are paid, set booking to <strong>confirmed</strong> and store <code>stripePaymentIntentId</code>.</li><li><strong>On error “requires authentication”</strong>: treat as 3DS; set slot to <code>requires_action</code>, store PI id, send email; no retries.</li><li><strong>Other errors</strong>: retry up to <strong>T48_MAX_RETRIES</strong> (2 = 3 attempts); then mark <strong>payment_failed</strong>.</li></ul><p>So: <strong>T-48 charge</strong> = charge one slot at a time when it enters the 48h window, with idempotency and retries.</p><hr><h2 id="_4-server-src-jobs-payoutjob-js" tabindex="-1">4. <code>server/src/jobs/payoutJob.js</code> <a class="header-anchor" href="#_4-server-src-jobs-payoutjob-js" aria-label="Permalink to &quot;4. `server/src/jobs/payoutJob.js`&quot;">​</a></h2><p><strong>What it is:</strong> A <strong>scheduled job</strong> that pays out instructors: moves money from their <strong>Stripe Connect balance</strong> to their <strong>bank</strong> (manual payout).</p><p><strong>What it does:</strong></p><ul><li>Find slots with <code>payoutStatus: &quot;pending&quot;</code>, <code>payoutEligibleAt &lt;= now</code>, <code>paymentStatus: &quot;paid&quot;</code>, <code>instructorAmount &gt; 0</code>.</li><li>For each, get instructor’s <strong>Stripe connected account</strong>.</li><li>Call <strong><code>createManualPayoutForInstructor</code></strong> with <code>accountId</code>, amount in centimes, metadata (bookingId, slotId).</li><li>On success: set slot <code>payoutStatus: &quot;completed&quot;</code>, <code>payoutId</code>, <code>payoutDate</code>, and create a <strong>transaction</strong> (type <code>payout</code>, role instructor, with <code>stripePayoutId</code>).</li><li>In <strong>non-production</strong>, if Stripe returns “insufficient funds”, still mark slot completed and create a simulated payout transaction so tests don’t block.</li></ul><p>So: <strong>payout</strong> = per-slot manual payout from instructor Stripe balance to bank, plus transaction record.</p><hr><h2 id="_5-server-src-graphql-resolvers-studentbooking-resolver-js" tabindex="-1">5. <code>server/src/graphql/resolvers/studentBooking.resolver.js</code> <a class="header-anchor" href="#_5-server-src-graphql-resolvers-studentbooking-resolver-js" aria-label="Permalink to &quot;5. `server/src/graphql/resolvers/studentBooking.resolver.js`&quot;">​</a></h2><p><strong>What it is:</strong> GraphQL resolvers for <strong>student bookings</strong>. This is where “create booking”, “redirect to Stripe”, and “complete after payment” are decided.</p><p><strong>Stripe/payment-related parts:</strong></p><ul><li><p><strong><code>isInstructorPaymentReady(instructor)</code></strong><br> Used before creating a paid booking: instructor must be payment-ready (profile complete, Stripe verified). So only instructors who finished Stripe onboarding can receive paid bookings.</p></li><li><p><strong><code>createStudentBooking</code> (instant card payment)</strong><br> If payment method is card and instructor is payment-ready:</p><ul><li>Computes commission split, then calls <strong><code>createPaymentIntentForBooking</code></strong> with <code>confirm: true</code> and <code>transferData</code> to instructor.</li><li>If <strong><code>requiresAction</code></strong> (3DS): returns <code>requiresAction: true</code>, <code>clientSecret</code>, <code>paymentIntentId</code> so the frontend can complete 3DS; booking is not saved yet.</li><li>If <strong>succeeded</strong>: saves booking with <code>stripePaymentIntentId</code>, all slots <strong>paid</strong>, and creates <strong>transactions</strong> (student, platform, instructor, commission).</li><li>If not succeeded and not requires_action: throws.</li></ul></li><li><p><strong><code>createBookingCheckoutSession</code></strong><br> Used when the student will pay on <strong>Stripe Checkout</strong> (redirect):</p><ul><li>Creates booking in DB with status <strong>pending</strong> and slots <strong>pending_payment</strong> (or similar).</li><li>If lesson is <strong>&gt;48h</strong> away: <strong>deferred</strong> → create Stripe <strong>Customer</strong>, then <strong>Checkout in setup mode</strong> (save card only). Success URL has <code>?checkout=setup_success&amp;session_id=...</code>.</li><li>If lesson is <strong>≤48h</strong>: <strong>instant</strong> → <strong>Checkout in payment mode</strong> (one payment for full amount, destination charge). Success URL has <code>?checkout=success&amp;session_id=...</code>.</li><li>Returns <strong><code>url</code></strong> (redirect to Stripe) and <strong>bookingId</strong>.</li></ul></li><li><p><strong><code>createCheckoutSessionForPendingBooking</code></strong><br> For <strong>pending</strong> bookings (e.g. student abandoned checkout or wants to resume): same 48h rule, creates either setup or payment Checkout Session, returns URL. Used for “Continue to checkout” on an existing pending booking.</p></li><li><p><strong><code>completeBookingFromCheckout</code></strong><br> When student returns from Stripe with <strong>payment</strong> mode and session <strong>paid</strong>: loads session, gets <code>bookingId</code> from metadata, updates booking to <strong>confirmed</strong>, sets all slots to <strong>paid</strong> and fills <code>stripePaymentIntentId</code>, charge amounts, commission. Idempotent (if webhook already updated, matchedCount 0 and we just return current booking).</p></li><li><p><strong><code>completeDeferredBookingFromCheckout</code></strong><br> When student returns from Stripe with <strong>setup</strong> mode: loads session and setup_intent, gets <strong>stripeCustomerId</strong> and <strong>payment method id</strong>, saves on booking, sets slots to <strong>pending_payment</strong>. Booking stays <strong>pending</strong> until T-48 job charges (or instant flow is not used for that booking).</p></li><li><p><strong><code>getClientSecretForT48SlotPayment</code></strong><br> For a slot that needs 3DS (e.g. T-48 returned <code>requires_action</code>): creates a <strong>new</strong> PaymentIntent for that slot (or reuses existing) with <code>confirm: false</code>, then <strong>confirms</strong> with <code>return_url</code> to your complete-payment page. Returns <strong>clientSecret</strong> so the frontend can either complete in-page or redirect to bank.</p></li><li><p><strong><code>completeT48SlotPayment</code></strong><br> After student completed 3DS: receives <strong>paymentIntentId</strong>, loads PI from Stripe, checks status <strong>succeeded</strong>. Finds booking/slot from metadata, marks slot <strong>paid</strong>, fills charge/commission, creates <strong>transactions</strong> (same shape as T-48 job and webhook). Returns updated booking.</p></li><li><p><strong><code>completeBookingAfterPayment</code></strong><br> Legacy/instant flow: after payment (e.g. 3DS) completed with a <strong>paymentIntentId</strong> that has booking metadata. Verifies PI succeeded and student id, then creates/updates booking with slots paid and creates transactions.</p></li></ul><p>So: this file <strong>orchestrates</strong> when to use Checkout vs on-site card, instant vs deferred, and how to finalize booking and transactions after payment.</p><hr><h2 id="_6-server-src-graphql-resolvers-refundrequest-resolver-js" tabindex="-1">6. <code>server/src/graphql/resolvers/refundRequest.resolver.js</code> <a class="header-anchor" href="#_6-server-src-graphql-resolvers-refundrequest-resolver-js" aria-label="Permalink to &quot;6. `server/src/graphql/resolvers/refundRequest.resolver.js`&quot;">​</a></h2><p><strong>What it is:</strong> Handles <strong>refund requests</strong>: student requests refund for a cancelled slot; admin approves or rejects. On approve, Stripe is called.</p><p><strong>Stripe/payment-related parts:</strong></p><ul><li><p><strong><code>requestRefund</code></strong><br> Validates that the slot is cancelled, <strong>paid</strong> (via <code>paymentStatus === &quot;paid&quot;</code> or presence of <code>stripePaymentIntentId</code>/<code>paymentIntentId</code> and <code>chargeAmount</code>), not already refunded, and no payout yet. Determines <strong>paymentIntentId</strong> = <code>booking.stripePaymentIntentId</code> (instant) or <strong>slot.paymentIntentId</strong> (T-48). Creates <strong>RefundRequest</strong> (pending). No Stripe call yet.</p></li><li><p><strong><code>approveRefundRequest</code></strong><br> When admin approves:</p><ol><li>Load booking and slot; re-check not already refunded and no payout.</li><li><strong>Transfer reversal:</strong> get <strong>Transfer</strong> id from PaymentIntent via <strong><code>getTransferIdFromPaymentIntent</code></strong>; if present and slot has <code>instructorAmount</code>, call <strong><code>createTransferReversal</code></strong> for the instructor’s share so the platform doesn’t lose money.</li><li><strong>Refund:</strong> <strong><code>createRefund</code></strong> with <code>paymentIntentId</code> and slot’s <code>chargeAmount</code> (in centimes). Partial refund for that slot.</li><li>Update slot: <code>status: &quot;refund&quot;</code>, <code>paymentStatus: &quot;refunded&quot;</code>, <code>refundedAt</code>, etc.</li><li>Create <strong>transactions</strong>: student credit (refund), instructor debit (reversal), platform debit (commission reversal). Save <strong>stripeRefundId</strong> on RefundRequest.</li><li>Update availability slot status to refund.</li></ol></li></ul><p>So: <strong>refunds</strong> = Stripe refund to card + transfer reversal for instructor share + transaction records.</p><hr><h2 id="_7-server-src-graphql-resolvers-js-instructor-stripe-connect" tabindex="-1">7. <code>server/src/graphql/resolvers.js</code> (Instructor Stripe Connect) <a class="header-anchor" href="#_7-server-src-graphql-resolvers-js-instructor-stripe-connect" aria-label="Permalink to &quot;7. `server/src/graphql/resolvers.js` (Instructor Stripe Connect)&quot;">​</a></h2><p><strong>What it is:</strong> Root GraphQL resolvers. Stripe-related mutations live here for <strong>instructor</strong> Connect onboarding and verification.</p><p><strong>Stripe-related mutations:</strong></p><ul><li><p><strong><code>createStripeAccount</code></strong><br> If instructor already has <strong>accountId</strong>: set manual payout schedule, create <strong>account link</strong>, return <strong>onboardingUrl</strong>. If not: <strong>createExpressAccount</strong>, <strong>setManualPayoutSchedule</strong>, save <strong>accountId</strong> and <strong>accountCreatedAt</strong> on instructor, create <strong>account link</strong>, return <strong>onboardingUrl</strong>. Frontend redirects instructor to Stripe.</p></li><li><p><strong><code>setInstructorPayoutToManual</code></strong> (Admin)<br> Calls <strong>setManualPayoutSchedule</strong> for the given instructor’s connected account.</p></li><li><p><strong><code>verifyStripeOnboarding</code></strong><br> Instructor clicks “I’ve completed onboarding”. Backend <strong>retrieves</strong> the Stripe account, runs <strong>accountToStripeSnapshot</strong>, updates instructor’s <strong>stripeAccount</strong> and <strong>onboardingStatus</strong> / <strong>isActive</strong>, returns charges_enabled / payouts_enabled.</p></li><li><p><strong><code>regenerateStripeLink</code></strong><br> If instructor didn’t finish onboarding: create a new <strong>account link</strong> and return <strong>onboardingUrl</strong>.</p></li></ul><p>So: <strong>Connect onboarding</strong> = create Express account, manual payout, account links, and verify status.</p><hr><h2 id="_8-server-src-graphql-utils-instructorpaymentready-js" tabindex="-1">8. <code>server/src/graphql/utils/instructorPaymentReady.js</code> <a class="header-anchor" href="#_8-server-src-graphql-utils-instructorpaymentready-js" aria-label="Permalink to &quot;8. `server/src/graphql/utils/instructorPaymentReady.js`&quot;">​</a></h2><p><strong>What it is:</strong> Small helper used by booking resolvers and frontend (via GraphQL) to decide if an instructor can receive paid bookings.</p><p><strong>What it does:</strong><br> Returns true only if instructor has <strong>isProfileComplete</strong>, <strong>isActive</strong>, and <strong>onboardingStatus === &quot;verified&quot;</strong>. So Stripe must be fully verified (and account active) before they appear as “payment ready”.</p><hr><h2 id="_9-server-src-services-transactionservice-js" tabindex="-1">9. <code>server/src/services/transactionService.js</code> <a class="header-anchor" href="#_9-server-src-services-transactionservice-js" aria-label="Permalink to &quot;9. `server/src/services/transactionService.js`&quot;">​</a></h2><p><strong>What it is:</strong> Service to create <strong>transaction</strong> documents in the DB.</p><p><strong>What it does:</strong><br><strong><code>createTransaction(opts)</code></strong> creates one transaction. <code>opts</code> include type, role, direction, amount, currency, status, bookingId, slotId, studentId, instructorId, and <strong>Stripe fields</strong>: <strong>stripePaymentIntentId</strong>, <strong>stripeRefundId</strong>, <strong>stripePayoutId</strong>, etc. Used by:</p><ul><li>studentBooking resolver (after instant payment),</li><li>stripeWebhook (payment_intent.succeeded),</li><li>t48ChargeJob,</li><li>payoutJob,</li><li>refundRequest resolver.</li></ul><p>So: <strong>all</strong> payment/refund/payout events that touch Stripe also create a transaction record with the relevant Stripe ids.</p><hr><h2 id="_10-server-src-graphql-resolvers-transaction-resolver-js" tabindex="-1">10. <code>server/src/graphql/resolvers/transaction.resolver.js</code> <a class="header-anchor" href="#_10-server-src-graphql-resolvers-transaction-resolver-js" aria-label="Permalink to &quot;10. `server/src/graphql/resolvers/transaction.resolver.js`&quot;">​</a></h2><p><strong>What it is:</strong> GraphQL resolvers for <strong>transactions</strong> and <strong>platform commission</strong> (admin).</p><p><strong>Stripe-related part:</strong><br><strong>Platform commission</strong> settings include <strong>payoutMethods</strong> (default <code>[&quot;Stripe&quot;]</code>). No direct Stripe API calls here; it just stores that the platform uses Stripe for payouts.</p><hr><h2 id="_11-server-src-index-js" tabindex="-1">11. <code>server/src/index.js</code> <a class="header-anchor" href="#_11-server-src-index-js" aria-label="Permalink to &quot;11. `server/src/index.js`&quot;">​</a></h2><p><strong>What it is:</strong> App entry point.</p><p><strong>Stripe-related part:</strong><br> Mounts the Stripe webhook <strong>before</strong> any JSON body parser:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;/webhooks/stripe&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  express.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">raw</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ type: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;application/json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }),</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  stripeWebhookRoutes,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>So <strong>POST /webhooks/stripe</strong> gets the raw body, which is required for <strong>Stripe-Signature</strong> verification.</p><hr><h2 id="_12-server-src-models-transaction-model-js" tabindex="-1">12. <code>server/src/models/transaction.model.js</code> <a class="header-anchor" href="#_12-server-src-models-transaction-model-js" aria-label="Permalink to &quot;12. `server/src/models/transaction.model.js`&quot;">​</a></h2><p><strong>What it is:</strong> Mongoose schema for <strong>transactions</strong>.</p><p><strong>Stripe-related fields:</strong></p><ul><li><strong>stripePaymentIntentId</strong></li><li><strong>stripeChargeId</strong></li><li><strong>stripeTransferId</strong></li><li><strong>stripePayoutId</strong></li><li><strong>stripeRefundId</strong></li><li><strong>stripeTransferReversalId</strong></li></ul><p>Used by <strong>transactionService</strong> and all code that logs payments, refunds, and payouts.</p><hr><h2 id="_13-server-src-models-studentbooking-model-js" tabindex="-1">13. <code>server/src/models/studentBooking.model.js</code> <a class="header-anchor" href="#_13-server-src-models-studentbooking-model-js" aria-label="Permalink to &quot;13. `server/src/models/studentBooking.model.js`&quot;">​</a></h2><p><strong>What it is:</strong> Mongoose schema for <strong>StudentBooking</strong> and embedded <strong>slots</strong>.</p><p><strong>Stripe/payment-related fields (conceptually):</strong></p><ul><li><strong>stripePaymentIntentId</strong> (booking-level for instant multi-slot payment)</li><li><strong>stripeCustomerId</strong> (for deferred/T-48 charging)</li><li><strong>paymentMethod</strong> (paymentMethodId, cardLast4, etc.)</li><li><strong>slots[].paymentStatus</strong> (pending_payment, paid, requires_action, payment_failed, refunded)</li><li><strong>slots[].paymentIntentId</strong> (T-48 per-slot PI)</li><li><strong>slots[].chargeAmount</strong>, <strong>instructorAmount</strong>, <strong>dspCommission</strong></li><li><strong>slots[].chargedAt</strong>, <strong>refundedAt</strong>, <strong>payoutStatus</strong>, <strong>payoutId</strong>, etc.</li></ul><p>So the <strong>booking and slot</strong> models are where Stripe state (who paid, which PI, refund/payout) is stored.</p><hr><h2 id="end-to-end-flow-summary" tabindex="-1">End-to-end flow summary <a class="header-anchor" href="#end-to-end-flow-summary" aria-label="Permalink to &quot;End-to-end flow summary&quot;">​</a></h2><ol><li><strong>Instructor:</strong> Connect with Stripe → <strong>resolvers.js</strong> (createExpressAccount, createAccountLink). After onboarding, <strong>verifyStripeOnboarding</strong> updates status. <strong>instructorPaymentReady</strong> then allows paid bookings.</li><li><strong>Student books (instant, card on file):</strong> <strong>studentBooking.resolver</strong> creates PaymentIntent with <strong>stripeService</strong>, confirms; on success saves booking + transactions. If 3DS, returns clientSecret; later <strong>completeBookingAfterPayment</strong> or <strong>completeT48SlotPayment</strong> finalizes.</li><li><strong>Student books (redirect):</strong> <strong>studentBooking.resolver</strong> creates <strong>pending</strong> booking, then Checkout Session (payment or setup) via <strong>stripeService</strong>. Student pays or saves card on Stripe. <strong>Webhook</strong> (checkout.session.completed) for setup saves customer/payment method; <strong>completeBookingFromCheckout</strong> / <strong>completeDeferredBookingFromCheckout</strong> finalize when student returns.</li><li><strong>T-48:</strong> <strong>t48ChargeJob</strong> charges each slot 48h before lesson using <strong>createPaymentIntentForBooking</strong> (off-session). If 3DS, slot set to requires_action; student uses <strong>getClientSecretForT48SlotPayment</strong> + <strong>completeT48SlotPayment</strong> to finish. <strong>Webhook</strong> payment_intent.succeeded also marks slot paid and creates transactions.</li><li><strong>Refunds:</strong> <strong>refundRequest.resolver</strong> approves → <strong>createTransferReversal</strong> (instructor share) + <strong>createRefund</strong> (student), then transactions.</li><li><strong>Payouts:</strong> <strong>payoutJob</strong> calls <strong>createManualPayoutForInstructor</strong> per eligible slot and records <strong>transaction</strong> with <strong>stripePayoutId</strong>.</li></ol><p>All Stripe API calls go through <strong>stripeService.js</strong>; all payment/refund/payout history goes through <strong>transactionService</strong> and <strong>transaction.model</strong> with Stripe IDs.</p><hr><h2 id="payout-availability-for-your-client-instructors" tabindex="-1">Payout availability (for your client / instructors) <a class="header-anchor" href="#payout-availability-for-your-client-instructors" aria-label="Permalink to &quot;Payout availability (for your client / instructors)&quot;">​</a></h2><p><strong>Question:</strong> When a student pays by card, the instructor’s share appears in their Stripe Connect account. When does it move from “Available soon” to “Available for payout”?</p><p><strong>Short answer (Switzerland, CH):</strong></p><ul><li>Yes: card payments first show as <strong>pending</strong> in the instructor’s connected account (Stripe Dashboard often labels this as <strong>“Available soon”</strong>).</li><li>Those funds become <strong>available for payout</strong> (can be sent to the instructor’s bank) after Stripe’s <strong>settlement</strong> period.</li><li>For <strong>Switzerland (CH)</strong> (<a href="https://docs.stripe.com/payments/balances" target="_blank" rel="noreferrer">Stripe docs – Balances and settlement time</a>): <ul><li><strong>Default (after the first payout):</strong> <strong>3 business days</strong> (Mon–Fri, excluding holidays). So a Monday charge is typically available on Thursday.</li><li><strong>First payout ever:</strong> Stripe uses a longer initial period. For CH, <strong>initial settlement</strong> is <strong>7 calendar days</strong>. The first payout is usually scheduled <strong>7–14 days</strong> after the first successful payment (can be longer depending on risk/country).</li></ul></li></ul><p><strong>What to tell the client:</strong></p><ul><li>“When a student pays by card, the instructor’s share appears in their Stripe account under <strong>‘Available soon’</strong>. It becomes <strong>available for payout</strong> (so we can pay it to their bank) after <strong>3 business days</strong> in Switzerland. For brand‑new instructors, the very first payout can take <strong>7–14 days</strong>.”</li><li>Optional: “Exact timing can vary by account and risk; instructors can see the exact date in their Stripe Dashboard.”</li></ul><p><strong>Source:</strong> <a href="https://docs.stripe.com/payments/balances" target="_blank" rel="noreferrer">Stripe – Balances and settlement time</a> (table “Country and settlement timing”: Switzerland – Initial 7 calendar days, Default 3 business days). <a href="https://docs.stripe.com/connect/account-balances" target="_blank" rel="noreferrer">Connect account balances</a>: connected accounts have the same pending → available flow; destination‑charge funds hit the connected account’s pending balance and then become available per that account’s country (CH = above).</p>',93)])])}const h=e(n,[["render",a]]);export{u as __pageData,h as default};
